        "<b>Архитектура:</b> асимметричный фасад, меандровый орнамент и редкая для самарской жилой архитектуры женская лепная герма.",
        "<b>Факты:</b> после революции дом национализировали и разделили на коммунальные квартиры; сегодня это объект культурного наследия."
