def strip_tags(value):
    return re.sub(
        r"\s+",
        " ",
        re.sub(r"<[^>]+>", " ", html_lib.unescape(value or ""))
    ).strip()


def extract_heritage_field(description, label):
    pattern = rf"{re.escape(label)}:\s*(.*?)(?:<br\s*/?>|$)"
    match = re.search(pattern, description or "", flags=re.IGNORECASE)
    if not match:
        return ""
    return strip_tags(match.group(1))


def load_heritage_objects(path=HERITAGE_GEOJSON):
    if not path.exists():
        return []

    data = json.loads(path.read_text(encoding="utf-8"))
    heritage_objects = []

    for feature in data.get("features", []):
        geometry = feature.get("geometry") or {}
        if geometry.get("type") != "Point":
            continue

        coordinates = geometry.get("coordinates") or []
        if len(coordinates) < 2:
            continue

        lon, lat = coordinates[:2]
        properties = feature.get("properties") or {}
        description = properties.get("description", "")
        category = extract_heritage_field(description, "Категория")

        heritage_objects.append(
            {
                "id": feature.get("id"),
                "name": strip_tags(properties.get("name", "")),
                "coords": [lat, lon],
                "registry": extract_heritage_field(
                    description,
                    "Регистрационный номер в реестре",
                ),
                "kind": extract_heritage_field(description, "Вид объекта"),
                "category": category,
                "created": extract_heritage_field(
                    description,
                    "Время создания объекта",
                ),
                "address": extract_heritage_field(description, "Адрес"),
                "protection": extract_heritage_field(
                    description,
                    "Документ принятия на охрану",
                ),
                "style_name": properties.get("styleName", ""),
            }
        )

    return heritage_objects


def heritage_marker_color(heritage_object):
    category = heritage_object.get("category", "").lower()
    style_name = heritage_object.get("style_name", "")

    if "федераль" in category or "federal" in style_name:
        return "red"
    if "регион" in category or "regional" in style_name:
        return "darkgreen"
    return "gray"


def build_heritage_popup_html(heritage_object):
    field_rows = [
        ("Адрес", heritage_object.get("address")),
        ("Категория", heritage_object.get("category")),
        ("Вид объекта", heritage_object.get("kind")),
        ("Время создания", heritage_object.get("created")),
        ("Регистрационный номер", heritage_object.get("registry")),
        ("Документ принятия на охрану", heritage_object.get("protection")),
    ]

    details_html = "".join(
        f'<div style="margin: 0 0 7px 0;">'
        f'<b>{label}:</b> {html_lib.escape(value)}'
        f'</div>'
        for label, value in field_rows
        if value
    )

    object_id = heritage_object.get("id")
    id_html = ""
    if object_id is not None:
        id_html = (
            '<div style="margin: 8px 0 0 0; color: #5f6368;">'
            f'GeoJSON ID: {html_lib.escape(str(object_id))}'
            '</div>'
        )

    return (
        '<div class="heritage-marker" style="'
        'font-size: 14px; '
        'line-height: 1.35; '
        'min-width: 280px; '
        'max-width: 360px;'
        '">'
        '<div style="'
        'font-size: 12px; '
        'font-weight: 700; '
        'letter-spacing: 0; '
        'color: #0b7d3b; '
        'margin: 0 0 6px 0;'
        '">Объект культурного наследия</div>'
        f'<b>{html_lib.escape(heritage_object["name"])}</b>'
        '<div style="height: 8px;"></div>'
        f'{details_html}'
        f'{id_html}'
        '</div>'
    )


# ==========================================
# 3. ОТРИСОВКА КАРТЫ С ПЕРЕКЛЮЧАТЕЛЯМИ УЛИЦ
# ==========================================

# ------------------------------------------
# Соответствие цвета маркера -> улица
# ------------------------------------------
marker_color_to_street = {
    "red": "Куйбышева",
    "blue": "Фрунзе",
    "green": "Ленинградская",
    "orange": "Самарская",
    "purple": "Молодогвардейская",
    "cadetblue": "Чапаевская",
    "beige": "Льва Толстого",
    "black": "Алексея Толстого",
    "darkred": "Степана Разина",
    "pink": "Галактионовская",
    "darkpurple": "Некрасовская",
    "lightred": "Пионерская",
    "darkblue": "Комсомольская",
    "darkgreen": "Венцека",
    "lightblue": "Водников",
    "lightgreen": "Садовая",
    "gray": "Рабочая",
    "lightgray": "Ленинская",
    "white": "Красноармейская",
}


# ------------------------------------------
# Создаем отдельный слой для каждой улицы
# ------------------------------------------
street_layers = {}

for street_name in streets:
    street_layers[street_name] = folium.FeatureGroup(
        name=f"🛣 {street_name}",
        overlay=True,
        control=True,
        show=False,   # True = улица включена при открытии карты
    )

    street_layers[street_name].add_to(samara_map)


class ShowAllStreetsControl(MacroElement):
    """Leaflet control that enables every street layer with one click."""

    def __init__(self, street_layer_names):
        super().__init__()
        self._name = "ShowAllStreetsControl"
        self.street_layer_names = street_layer_names
        self._template = Template(
            """
            {% macro script(this, kwargs) %}
            (function() {
                const streetLayers = [
                    {% for layer_name in this.street_layer_names %}
                    {{ layer_name }},
                    {% endfor %}
                ];

                const ShowAllStreets = L.Control.extend({
                    options: {
                        position: "topleft"
                    },

                    onAdd: function(map) {
                        const container = L.DomUtil.create(
                            "div",
                            "leaflet-bar show-all-streets-control"
                        );

                        const button = L.DomUtil.create(
                            "button",
                            "",
                            container
                        );

                        button.type = "button";
                        button.textContent = "Показать все улицы";
                        button.title = "Показать все улицы";
                        button.setAttribute(
                            "aria-label",
                            "Показать все улицы"
                        );

                        button.style.background = "#ffffff";
                        button.style.border = "0";
                        button.style.borderRadius = "4px";
                        button.style.boxShadow = "0 1px 5px rgba(0,0,0,.35)";
                        button.style.cursor = "pointer";
                        button.style.fontSize = "13px";
                        button.style.fontWeight = "600";
                        button.style.lineHeight = "1.2";
                        button.style.padding = "8px 10px";
                        button.style.whiteSpace = "nowrap";

                        L.DomEvent.disableClickPropagation(container);
                        L.DomEvent.disableScrollPropagation(container);

                        L.DomEvent.on(button, "click", function(event) {
                            L.DomEvent.preventDefault(event);

                            streetLayers.forEach(function(layer) {
                                if (!map.hasLayer(layer)) {
                                    map.addLayer(layer);
                                }
                            });
                        });

                        return container;
                    }
                });

                {{ this._parent.get_name() }}.addControl(
                    new ShowAllStreets()
                );
            })();
            {% endmacro %}
            """
        )


ShowAllStreetsControl(
    [layer.get_name() for layer in street_layers.values()]
).add_to(samara_map)


# ------------------------------------------
# Линии улиц
# ------------------------------------------
for street_name, data in streets.items():

    layer = street_layers[street_name]

    if not data.get("coords"):
        continue

    # Полупрозрачная подложка / коридор
    if data.get("highlight_weight", 0) > 1:
        folium.PolyLine(
            locations=data["coords"],
            color=data["color"],
            weight=data["highlight_weight"],
            opacity=0.18,
            tooltip=f"Улица {street_name}"
        ).add_to(layer)

    # Основная линия
    folium.PolyLine(
        locations=data["coords"],
        color=data["color"],
        weight=6,
        opacity=0.8,
        tooltip=f"Улица {street_name}"
    ).add_to(layer)


# ------------------------------------------
# HTML всплывающего окна
# ------------------------------------------
def build_popup_html(place):
    details = (
        place["info"]
        if isinstance(place["info"], list)
        else [place["info"]]
    )

    detail_html = "".join(
        f'<div style="margin: 0 0 7px 0;">{line}</div>'
        for line in details
    )

    image_html = ""

    if place.get("image_url"):
        caption = place.get(
            "image_caption",
            place["name"]
        )

        image_html = (
            f'<img class="popup-thumb" '
            f'src="{place["image_url"]}" '
            f'alt="{caption}" '
            f'style="'
            f'width: 100%; '
            f'height: 150px; '
            f'object-fit: cover; '
            f'border-radius: 6px; '
            f'margin: 0 0 9px 0;'
            f'">'
        )

    return (
        '<div style="'
        'font-size: 14px; '
        'line-height: 1.35; '
        'min-width: 270px; '
        'max-width: 340px;'
        '">'
        f'{image_html}'
        f'<b>{place["name"]}</b>'
        '<div style="height: 8px;"></div>'
        f'{detail_html}'
        '</div>'
    )


# ------------------------------------------
# Маркеры распределяем по слоям улиц
# ------------------------------------------
for place in places:

    street_name = place.get("street") or marker_color_to_street.get(
        place["color"]
    )

    # Если цвет не привязан к улице —
    # добавляем маркер просто на карту
    target_layer = street_layers.get(
        street_name,
        samara_map
    )

    folium.Marker(
        location=place["coords"],

        popup=folium.Popup(
            build_popup_html(place),
            max_width=380
        ),

        tooltip=place["name"],

        icon=folium.Icon(
            color=place["color"],
            icon_color=place.get(
                "icon_color",
                "white"
            ),
            icon=place.get(
                "icon",
                "info-sign"
            )
        )

    ).add_to(target_layer)


# ------------------------------------------
# Отдельный слой объектов культурного наследия
# ------------------------------------------
heritage_layer = folium.FeatureGroup(
    name="✓ Объекты культурного наследия",
    overlay=True,
    control=True,
    show=False,
)
heritage_layer.add_to(samara_map)

for heritage_object in load_heritage_objects():
    folium.Marker(
        location=heritage_object["coords"],

        popup=folium.Popup(
            build_heritage_popup_html(heritage_object),
            max_width=400
        ),

        tooltip=heritage_object["name"],

        icon=folium.Icon(
            color=heritage_marker_color(heritage_object),
            icon_color="white",
            icon="ok-sign",
            prefix="glyphicon",
        )

    ).add_to(heritage_layer)


# ------------------------------------------
# Переключатель слоев
# ------------------------------------------
folium.LayerControl(
    position="topright",
    collapsed=False
).add_to(samara_map)


# ------------------------------------------
# Сохранение
# ------------------------------------------
samara_map.save(
    "samara_marathon_map.html"
)

print(
    "Карта успешно обновлена: "
    "samara_marathon_map.html"
)
